select 'Constraints, FKs e ações de exclusão' verificacao, (select coalesce(jsonb_agg(to_jsonb(v)), '[]'::jsonb) from (select n.nspname||'.'||t.relname objeto,c.conname nome,c.contype::text tipo,c.convalidated validada,c.condeferrable adiavel,c.condeferred inicialmente_adiada,pg_get_constraintdef(c.oid) definicao from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname||'.'||t.relname in ('public.quotes','private.quote_counters') and c.contype<>'n' order by 1,c.conname) v)='[{"nome":"quote_counters_company_id_fkey","tipo":"f","objeto":"private.quote_counters","adiavel":false,"validada":true,"definicao":"FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE","inicialmente_adiada":false},{"nome":"quote_counters_last_number_check","tipo":"c","objeto":"private.quote_counters","adiavel":false,"validada":true,"definicao":"CHECK (((last_number >= 1) AND (last_number <= ''9007199254740990''::bigint)))","inicialmente_adiada":false},{"nome":"quote_counters_pkey","tipo":"p","objeto":"private.quote_counters","adiavel":false,"validada":true,"definicao":"PRIMARY KEY (company_id)","inicialmente_adiada":false},{"nome":"quotes_check","tipo":"c","objeto":"public.quotes","adiavel":false,"validada":true,"definicao":"CHECK (((jsonb_typeof(client_snapshot) = ''object''::text) AND ((client_snapshot ->> ''id''::text) IS NOT NULL) AND ((client_snapshot ->> ''id''::text) = (client_id)::text)))","inicialmente_adiada":false},{"nome":"quotes_check1","tipo":"c","objeto":"public.quotes","adiavel":false,"validada":true,"definicao":"CHECK ((valid_until >= date))","inicialmente_adiada":false},{"nome":"quotes_check2","tipo":"c","objeto":"public.quotes","adiavel":false,"validada":true,"definicao":"CHECK (((discount_value >= 0) AND ((discount_kind <> ''percent''::text) OR (discount_value <= 10000))))","inicialmente_adiada":false},{"nome":"quotes_check3","tipo":"c","objeto":"public.quotes","adiavel":false,"validada":true,"definica