 1) AND (jsonb_array_length(items) <= 100))))","inicialmente_adiada":false},{"nome":"quotes_notes_check","tipo":"c","objeto":"public.quotes","adiavel":false,"validada":true,"definicao":"CHECK ((char_length(notes) <= 4000))","inicialmente_adiada":false},{"nome":"quotes_number_check","tipo":"c","objeto":"public.quotes","adiavel":false,"validada":true,"definicao":"CHECK (((number >= 1) AND (number <= ''9007199254740990''::bigint)))","inicialmente_adiada":false},{"nome":"quotes_payment_terms_check","tipo":"c","objeto":"public.quotes","adiavel":false,"validada":true,"definicao":"CHECK ((char_length(payment_terms) <= 2000))","inicialmente_adiada":false},{"nome":"quotes_pkey","tipo":"p","objeto":"public.quotes","adiavel":false,"validada":true,"definicao":"PRIMARY KEY (id)","inicialmente_adiada":false},{"nome":"quotes_revision_check","tipo":"c","objeto":"public.quotes","adiavel":false,"validada":true,"definicao":"CHECK (((revision >= 1) AND (revision <= ''9007199254740991''::bigint)))","inicialmente_adiada":false},{"nome":"quotes_status_check","tipo":"c","objeto":"public.quotes","adiavel":false,"validada":true,"definicao":"CHECK ((status = ANY (ARRAY[''draft''::text, ''sent''::text, ''approved''::text, ''rejected''::text, ''expired''::text])))","inicialmente_adiada":false},{"nome":"quotes_subtotal_cents_check","tipo":"c","objeto":"public.quotes","adiavel":false,"validada":true,"definicao":"CHECK (((subtotal_cents >= 0) AND (subtotal_cents <= ''1000000000000''::bigint)))","inicialmente_adiada":false}]'::jsonb correto, 'Contrato integral da migration; diferenças de formatação/versão exigem revisão, nunca reaplicação.' observacao
