select 'Políticas completas, incluindo extras' verificacao, (select coalesce(jsonb_agg(to_jsonb(v)), '[]'::jsonb) from (select n.nspname||'.'||t.relname objeto,p.polname nome,p.polcmd::text comando,p.polpermissive permissiva,(select array_agg(coalesce(r.rolname::text,'PUBLIC') order by coalesce(r.rolname::text,'PUBLIC')) from unnest(p.polroles) id left join pg_roles r on r.oid=id) papeis,pg_get_expr(p.polqual,p.polrelid) filtro,pg_get_expr(p.polwithcheck,p.polrelid) validacao from pg_policy p join pg_class t on t.oid=p.polrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname||'.'||t.relname in ('public.quotes','private.quote_counters') order by 1,p.polname) v)='[{"nome":"quotes_create","filtro":null,"objeto":"public.quotes","papeis":["authenticated"],"comando":"a","validacao":"private.has_quotes_access(company_id, ''create''::text)","permissiva":true},{"nome":"quotes_delete","filtro":"private.has_quotes_access(company_id, ''delete''::text)","objeto":"public.quotes","papeis":["authenticated"],"comando":"d","validacao":null,"permissiva":true},{"nome":"quotes_read","filtro":"private.has_quotes_access(company_id, ''read''::text)","objeto":"public.quotes","papeis":["authenticated"],"comando":"r","validacao":null,"permissiva":true},{"nome":"quotes_update","filtro":"private.has_quotes_access(company_id, ''update''::text)","objeto":"public.quotes","papeis":["authenticated"],"comando":"w","validacao":"private.has_quotes_access(company_id, ''update''::text)","permissiva":true}]'::jsonb correto, 'Contrato integral da migration; diferenças de formatação/versão exigem revisão, nunca reaplicação.' observacao
union all
select 'Funções: assinatura, corpo integral e segurança' verificacao, (select coalesce(jsonb_agg(to_jsonb(v)), '[]'::jsonb) from (select n.nspname||'.'||p.proname nome,pg_get_function_identity_arguments(p.oid) argumentos,pg_get_function_result(p.oid) retorno,l.lanname linguagem,p.prokind::text especie,p.provolatile::text volatilidade,p.prosecdef definer,p.proleakproof leakproof,p.proisstrict estrita,p.proparallel::text paralelismo,p.pronargdefaults defaults,p.proconfig config,btrim(replace(p.prosrc,chr(13)||chr(10),chr(10))) corpo from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('public','private') and p.proname in ('has_quotes_access','require_quote_access','validate_quote_input','capture_quote_client','create_quote','update_quote','remove_quote') order by 1,2) v)='[{"nome":"private.capture_quote_client","corpo":"\ndeclare v_snapshot jsonb;\nbegin\n select jsonb_build_object(''id'',c.id,''name'',c.name,''type'',c.type,''document'',c.document,''phone'',c.phone,''email'',c.email,''address'',c.address,''city'',c.city,''state'',c.state)\n into v_snapshot from public.clients c where c.id=p_client_id and c.company_id=p_company_id for share of c;\n if not found then raise exception ''Client unavailable in company'' using errcode=''P0002''; end if;\n return v_snapshot;\nend;\n","config":["search_path=\"\""],"definer":false,"especie":"f","estrita":false,"retorno":"jsonb","defaults":0,"leakproof":false,"linguagem":"plpgsql","argumentos":"p_company_id uuid, p_client_id uuid","paralelismo":"u","volatilidade":"v"},{"nome":"private.has_quotes_access","corpo":"\n select exists(select 1 from public.company_memberships m join auth.users u on u.id=m.user_id\n  where m.company_id=p_company_id and m.user_id=auth.uid() and u.email_confirmed_at is not null\n  and case p_operation when ''read'' then m.role in (''owner'',''admin'',''member'',''viewer'')\n    when ''create'' then m.role in (''owner'',''admin'',''member'')\n    when ''update'' then m.role in (''owner'',''admin'',''member'')\n    when ''delete'' then m.role in (''owner'',''admin'') else false end);\n","config":["search_path=\"\""],"definer":true,"especie":"f","estrita":false,"retorno":"boolean","defaults":0,"leakproof":false,"linguagem":"sql","argumentos":"p_company_id uuid, p_operation text","paralelismo":"u","volatilidade":"s"},{"nome":"private.require_quote_access","corpo":"\ndeclare v_role public.company_role;\nbegin\n select m.role into v_role from public.company_memberships m join auth.users u on u.id=m.user_id\n where m.company_id=p_company_id and m.user_id=auth.uid() and u.email_confirmed_at is not null for share of m;\n if not found or not (case p_operation when ''create'' then v_role in (''owner'',''admin'',''member'')\n  when ''update'' then v_role in (''owner'',''admin'',''member'') when ''delete'' then v_role in (''owner'',''admin'') else false end) then\n  raise exception ''Quote permission required'' using errcode=''42501'';\n end if;\nend;\n","config":["search_path=\"\""],"definer":false,"especie":"f","estrita":false,"retorno":"void","defaults":0,"leakproof":false,"linguagem":"plpgsql","argumentos":"p_company_id uuid, p_operation text","paralelismo":"u","volatilidade":"v"},{"nome":"private.validate_quote_input","corpo":"\ndeclare v_item jsonb; v_items jsonb:=''[]''::jsonb; v_ids text[]:=''{}''; v_id text;\n v_qty numeric; v_price numeric; v_line numeric; v_subtotal numeric:=0; v_value numeric; v_discount numeric; v_kind text;\n v_date date; v_until date; v_client uuid;\nbegin\n if jsonb_typeof(p_input) is distinct from ''object'' then raise exception ''Invalid quote'' using errcode=''22023''; end if;\n if jsonb_typeof(p_input->''clientId'') is distinct from ''string'' or (p_input->>''clientId'') !~* ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' then raise exception ''Invalid client'' using errcode=''22023''; end if;\n v_client:=(p_input->>''clientId'')::uuid;\n if jsonb_typeof(p_input->''date'') is distinct from ''string'' or jsonb_typeof(p_input->''validUntil'') is distinct from ''string''\n or (p_input->>''date'') !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$'' or (p_input->>''validUntil'') !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$'' then raise exception ''Invalid dates'' using errcode=''22023''; end if;\n v_date:=(p_input->>''date'')::date; v_until:=(p_input->>''validUntil'')::date;\n if v_until<v_date then raise exception ''Invalid validity'' using errcode=''22023''; end if;\n if jsonb_typeof(p_input->''status'') is distinct from ''string'' or p_input->>''status'' not in (''draft'',''sent'',''approved'',''rejected'',''expired'') then raise exception ''Invalid status'' using errcode=''22023''; end if;\n if p_input->>''status''=''expired'' and v_until>=(now() at time zone ''America/Sao_Paulo'')::date then raise exception ''Quote has not expired'' using errcode=''22023''; end if;\n if jsonb_typeof(p_input->''notes'') is distinct from ''string'' or char_length(p_input->>''notes'')>4000\n or jsonb_typeof(p_input->''paymentTerms'') is distinct from ''string'' or char_length(p_input->>''paymentTerms'')>2000 then raise exception ''Invalid quote text'' using errcode=''22023''; end if;\n if jsonb_typeof(p_input->''items'') is distinct from ''array'' then raise exception ''Invalid items'' using errcode=''22023''; end if;\n if jsonb_array_length(p_input->''items'') not between 1 and 100 then raise exception ''Invalid item count'' using errcode=''22023''; end if;\n for v_item in select value from jsonb_array_elements(p_input->''items'') loop\n  if jsonb_typeof(v_item) is distinct from ''object'' or jsonb_typeof(v_item->''id'') is distinct from ''string''\n   or char_length(v_item->>''id'') not between 1 and 100\n   or jsonb_typeof(v_item->''description'') is distinct from ''string'' or char_length(btrim(v_item->>''description''))<1 or char_length(v_item->>''description'')>300\n   or jsonb_typeof(v_item->''unit'') is distinct from ''string'' or char_length(btrim(v_item->>''unit''))<1 or char_length(v_item->>''unit'')>20\n   or jsonb_typeof(v_item->''quantityMilli'') is distinct from ''number'' or jsonb_typeof(v_item->''unitPriceCents'') is distinct from ''number'' then raise exception ''Invalid item fields'' using errcode=''22023''; end if;\n  v_id:=v_item->>''id''; if v_id=any(v_ids) then raise exception ''Duplicate item ID'' using errcode=''22023''; end if; v_ids:=array_append(v_ids,v_id);\n  v_qty:=(v_item->>''quantityMilli'')::numeric; v_price:=(v_item->>''unitPriceCents'')::numeric;\n  if v_qty<>trunc(v_qty) or v_price<>trunc(v_price) or v_qty not between 1 and 1000000000 or v_price not between 0 and 10000000000 then raise exception ''Invalid item values'' using errcode=''22023''; end if;\n  v_line:=floor((v_qty*v_price+500)/1000); v_subtotal:=v_subtotal+v_line;\n  if v_subtotal>1000000000000 then raise exception ''Quote total limit'' using errcode=''22023''; end if;\n  v_items:=v_items||jsonb_build_array(jsonb_build_object(''id'',v_id,''description'',btrim(v_item->>''description''),''unit'',btrim(v_item->>''unit''),''quantityMilli'',v_qty,''unitPriceCents'',v_price));\n end loop;\n if jsonb_typeof(p_input->''discount'') is distinct from ''object'' or jsonb_typeof(p_input->''discount''->''kind'') is distinct from ''string''\n or p_input->''discount''->>''kind'' not in (''fixed'',''percent'') or jsonb_typeof(p_input->''discount''->''value'') is distinct from ''number'' then raise exception ''Invalid discount'' using errcode=''22023''; end if;\n v_kind:=p_input->''discount''->>''kind'';v_value:=(p_input->''discount''->>''value'')::numeric;\n if v_value<>trunc(v_value) or v_value<0 or v_value>1000000000000 or (v_kind=''percent'' and v_value>10000) then raise exception ''Invalid discount value'' using errcode=''22023''; end if;\n v_discount:=case when v_kind=''fixed'' then v_value else floor((v_subtotal*v_value+5000)/10000) end;\n if v_discount>v_subtotal then raise exception ''Discount exceeds subtotal'' using errcode=''22023''; end if;\n return jsonb_build_object(''clientId'',v_client,''date'',v_date,''validUntil'',v_until,''status'',p_input->>''status'',''items'',v_items,\n  ''discount'',jsonb_build_object(''kind'',v_kind,''value'',v_value),''notes'',btrim(p_input->>''notes''),''paymentTerms'',btrim(p_input->>''paymentTerms''),\n  ''subtotal'',v_subtotal,''discountCents'',v_discount,''total'',v_subtotal-v_discount);\nend;\n","config":["search_path=\"\""],"definer":false,"especie":"f","estrita":false,"retorno":"jsonb","defaults":0,"leakproof":false,"linguagem":"plpgsql","argumentos":"p_input jsonb","paralelismo":"u","volatilidade":"v"},{"nome":"public.create_quote","corpo":"\ndeclare v jsonb; v_snapshot jsonb; v_name text; v_number bigint; v_row public.quotes;\nbegin\n perform private.require_quote_access(p_company_id,''create'');\n v:=private.validate_quote_input(p_input);v_snapshot:=private.capture_quote_client(p_company_id,(v->>''clientId'')::uuid);\n select c.name into v_name from public.companies c where c.id=p_company_id;\n insert into private.quote_counters as counter(company_id,last_number) values(p_company_id,1)\n on conflict(company_id) do update set last_number=counter.last_number+1 where counter.last_number<9007199254740990 returning last_number into v_number;\n if v_number is null then raise exception ''Quote number limit'' using errcode=''22023''; end if;\n insert into public.quotes(company_id,number,client_id,client_snapshot,company_snapshot,date,valid_until,status,items,discount_kind,discount_value,subtotal_cents,discount_cents,total_cents,notes,payment_terms,issued_at)\n values(p_company_id,v_number,(v->>''clientId'')::uuid,v_snapshot,jsonb_build_object(''name'',v_name),(v->>''date'')::date,(v->>''validUntil'')::date,v->>''status'',v->''items'',v->''discount''->>''kind'',(v->''discount''->>''value'')::bigint,(v->>''subtotal'')::bigint,(v->>''discountCents'')::bigint,(v->>''total'')::bigint,v->>''notes'',v->>''paymentTerms'',case when v->>''status''=''draft'' then null else now() end) returning * into v_row;\n return next v_row;\nend;\n","config":["search_path=\"\""],"definer":true,"especie":"f","estrita":false,"retorno":"SETOF quotes","defaults":0,"leakproof":false,"linguagem":"plpgsql","argumentos":"p_company_id uuid, p_input jsonb","paralelismo":"u","volatilidade":"v"},{"nome":"public.remove_quote","corpo":"\ndeclare v_previous public.quotes;\nbegin\n perform private.require_quote_access(p_company_id,''delete'');\n select * into v_previous from public.quotes q where q.id=p_quote_id and q.company_id=p_company_id for update;\n if not found then raise exception ''Quote unavailable in company'' using errcode=''P0002''; end if;\n if p_revision is null or v_previous.revision<>p_revision then raise exception ''Stale quote revision'' using errcode=''40001''; end if;\n delete from public.quotes where id=p_quote_id and company_id=p_company_id;\nend;\n","config":["search_path=\"\""],"definer":true,"especie":"f","estrita":false,"retorno":"void","defaults":0,"leakproof":false,"linguagem":"plpgsql","argumentos":"p_company_id uuid, p_quote_id uuid, p_revision bigint","paralelismo":"u","volatilidade":"v"},{"nome":"public.update_quote","corpo":"\ndeclare v jsonb; v_previous public.quotes; v_row public.quotes; v_snapshot jsonb;\nbegin\n perform private.require_quote_access(p_company_id,''update'');\n select * into v_previous from public.quotes q where q.id=p_quote_id and q.company_id=p_company_id for update;\n if not found then raise exception ''Quote unavailable in company'' using errcode=''P0002''; end if;\n if p_revision is null or v_previous.revision<>p_revision then raise exception ''Stale quote revision'' using errcode=''40001''; end if;\n v:=private.validate_quote_input(p_input);\n if v_previous.issued_at is not null then\n  if (v->>''clientId'')::uuid<>v_previous.client_id then raise exception ''Issued client is immutable'' using errcode=''22023''; end if;\n  v_snapshot:=v_previous.client_snapshot;\n else v_snapshot:=private.capture_quote_client(p_company_id,(v->>''clientId'')::uuid);end if;\n update public.quotes set client_id=(v->>''clientId'')::uuid,client_snapshot=v_snapshot,date=(v->>''date'')::date,valid_until=(v->>''validUntil'')::date,\n status=v->>''status'',items=v->''items'',discount_kind=v->''discount''->>''kind'',discount_value=(v->''discount''->>''value'')::bigint,\n subtotal_cents=(v->>''subtotal'')::bigint,discount_cents=(v->>''discountCents'')::bigint,total_cents=(v->>''total'')::bigint,\n notes=v->>''notes'',payment_terms=v->>''paymentTerms'',revision=revision+1,\n issued_at=coalesce(v_previous.issued_at,case when v->>''status''=''draft'' then null else now() end)\n where id=p_quote_id and company_id=p_company_id returning * into v_row;\n return next v_row;\nend;\n","config":["search_path=\"\""],"definer":true,"especie":"f","estrita":false,"retorno":"SETOF quotes","defaults":0,"leakproof":false,"linguagem":"plpgsql","argumentos":"p_company_id uuid, p_quote_id uuid, p_revision bigint, p_input jsonb","paralelismo":"u","volatilidade":"v"}]'::jsonb correto, 'Contrato integral da migration; diferenças de formatação/versão exigem revisão, nunca reaplicação.' observacao
union all
select 'Triggers de aplicação' verificacao, (select coalesce(jsonb_agg(to_jsonb(v)), '[]'::jsonb) from (select n.nspname||'.'||t.relname objeto,g.tgname nome,g.tgtype tipo,g.tgenabled::text estado,g.tgnargs argumentos,pg_get_expr(g.tgqual,g.tgrelid) filtro,pn.nspname||'.'||p.proname funcao,encode(g.tgargs,'hex') valores from pg_trigger g join pg_class t on t.oid=g.tgrelid join pg_namespace n on n.oid=t.relnamespace join pg_proc p on p.oid=g.tgfoid join pg_namespace pn on pn.oid=p.pronamespace where n.nspname||'.'||t.relname in ('public.quotes','private.quote_counters') and not g.tgisinternal order by 1,g.tgname) v)='[{"nome":"quotes_updated","tipo":19,"estado":"O","filtro":null,"funcao":"private.touch_updated_at","objeto":"public.quotes","valores":"","argumentos":0}]'::jsonb correto, 'Contrato integral da migration; diferenças de formatação/versão exigem revisão, nunca reaplicação.' observacao

-- Effective privileges also catch inherited/column grants and altered default ACLs.
union all select 'Privilégios efetivos de tabela',not exists(
 select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
 cross join (values ('anon'),('authenticated')) r(papel)
 cross join (values ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) v(privilegio)
 where n.nspname||'.'||c.relname in ('public.quotes','private.quote_counters')
 and has_table_privilege(r.papel,c.oid,v.privilegio) is distinct from (r.papel='authenticated' and n.nspname='public' and v.privilegio='SELECT')),
 'authenticated: somente SELECT em quotes; nenhum acesso ao contador. anon: nenhum acesso.'
union all select 'Privilégios efetivos por coluna',not exists(
 select 1 from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace
 cross join (values ('anon'),('authenticated')) r(papel) cross join (values ('SELECT'),('INSERT'),('UPDATE'),('REFERENCES')) v(privilegio)
 where n.nspname||'.'||c.relname in ('public.quotes','private.quote_counters') and a.attnum>0 and not a.attisdropped
 and has_column_privilege(r.papel,c.oid,a.attnum,v.privilegio) is distinct from (r.papel='authenticated' and n.nspname='public' and v.privilegio='SELECT')),
 'Nenhuma escrita por coluna; sem acesso ao contador.'
union all select 'EXECUTE efetivo e nenhum grant PUBLIC',not exists(
 select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join (values ('anon'),('authenticated')) r(papel)
 where n.nspname in ('public','private') and p.proname in ('has_quotes_access','require_quote_access','validate_quote_input','capture_quote_client','create_quote','update_quote','remove_quote')
 and has_function_privilege(r.papel,p.oid,'EXECUTE') is distinct from (r.papel='authenticated' and ((n.nspname='public' and p.proname in ('create_quote','update_quote','remove_quote')) or (n.nspname='private' and p.proname='has_quotes_access'))))
 and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where n.nspname in ('public','private') and p.proname in ('has_quotes_access','require_quote_access','validate_quote_input','capture_quote_client','create_quote','update_quote','remove_quote') and a.grantee=0),
 'Somente helper RLS e três RPCs executáveis por authenticated; internos/anon/PUBLIC bloqueados.'
union all select 'Nenhum grant PUBLIC nas tabelas ou colunas',not exists(
 select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a where n.nspname||'.'||c.relname in ('public.quotes','private.quote_counters') and a.grantee=0)
 and not exists(select 1 from pg_attribute att join pg_class c on c.oid=att.attrelid join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(att.attacl) a where n.nspname||'.'||c.relname in ('public.quotes','private.quote_counters') and a.grantee=0),
 'PUBLIC sem grants, inclusive por coluna.'
union all select 'Proprietários confiáveis e API sem bypass',
 (select count(*)=2 and bool_and(not rolsuper and not rolbypassrls) from pg_roles where rolname in ('anon','authenticated'))
 and exists(select 1 from pg_proc b where b.oid=to_regprocedure('private.is_company_member(uuid)'))
 and not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname||'.'||c.relname in ('public.quotes','private.quote_counters') and (c.relowner is distinct from (select proowner from pg_proc where oid=to_regprocedure('private.is_company_member(uuid)')) or pg_has_role('authenticated',c.relowner,'USAGE') or pg_has_role('anon',c.relowner,'USAGE')))
 and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname in ('has_quotes_access','require_quote_access','validate_quote_input','capture_quote_client','create_quote','update_quote','remove_quote') and (p.proowner is distinct from (select proowner from pg_proc where oid=to_regprocedure('private.is_company_member(uuid)')) or pg_has_role('authenticated',p.proowner,'USAGE') or pg_has_role('anon',p.proowner,'USAGE'))),
 'Objetos novos com o dono do helper inicial; API não pode assumir seus privilégios.'
union all select 'Schemas e timestamp reutilizado',
 has_schema_privilege('authenticated','private','USAGE') and has_schema_privilege('authenticated','public','USAGE')
 and not has_schema_privilege('authenticated','private','CREATE') and not has_schema_privilege('anon','private','CREATE')
 and exists(select 1 from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure('private.touch_updated_at()') and l.lanname='plpgsql' and p.prorettype='trigger'::regtype and not p.prosecdef and p.proconfig=array['search_path=""'] and lower(btrim(regexp_replace(p.prosrc,'[[:space:]]+',' ','g')))='begin new.updated_at := pg_catalog.now(); return new; end;'),
 'USAGE sem CREATE em private; helper de timestamp inicial preservado.'
)
select verificacao,case when coalesce(correto,false) then 'OK' else 'REVISAR' end resultado,observacao from checagens order by verificacao;
